import type {ServiceInventory} from '@/lib/service-inventory';
export function ServiceInventoryReview({inventory}:{inventory?:ServiceInventory}){
 if(!inventory)return <p className="pilot-report-basis">Inventory snapshots are not available for this preview. Historical capacity cannot be established from this close.</p>;
 return <section><h3>Inventory to preserve for {inventory.service_date}</h3><p>Review the current room configuration and dated maintenance exclusions. These figures will be saved with this close; they do not reconstruct earlier room configuration.</p>{!inventory.complete&&<p className="pilot-error">Capacity is incomplete. Historical occupancy percentages and revenue per available unit will be unavailable for this day.</p>}<div className="pilot-table-wrap"><table className="pilot-table"><caption>Reviewed inventory by room type</caption><thead><tr><th scope="col">Room type</th><th scope="col">Physical units</th><th scope="col">Maintenance exclusions</th><th scope="col">Selling ceiling</th><th scope="col">Effective units</th></tr></thead><tbody>{inventory.room_types.map(r=><tr key={r.room_type_id}><th scope="row">{r.room_type_name}</th><td>{r.physical_units}</td><td>{r.closed_units}</td><td>{r.configured_units??'Unknown'}</td><td>{r.effective_units??'Unknown'}</td></tr>)}</tbody><tfoot><tr><th scope="row">Total</th><td>{inventory.physical_units}</td><td>{inventory.closed_units}</td><td>{inventory.configured_units??'Unknown'}</td><td>{inventory.effective_units??'Unknown'}</td></tr></tfoot></table></div></section>;
}
